operations.after:
job.timer = this.timers.setTimeout(() => {
  try {
    const scope = typeof job.scope === 'string' ? job.scope : '';
    const scopeKind = scope.startsWith('admit:') ? 'admit' : scope.startsWith('project:') ? 'project' : scope.startsWith('reconcile:') ? 'reconcile' : scope === 'piece' ? 'piece' : scope === 'rush-guidance' ? 'rush-guidance' : 'other';
    globalThis.__boardAdmissionRulesTimeout?.({ jobId:job.id, type:['project','equivalent','previews','rush-guidance'].includes(job.type) ? job.type : 'other', scopeKind, active:this.running === job });
  } catch {}
  finish(Object.assign(new Error("Rules calculation timed out"), { code: "rules_timeout" }));
}, this.timeoutMs);
